def agent_check_registry_coverage(codes, mandatory=None):
    REQUIRED = ['AGENT-DESIGN', 'AGENT-SECURITY']
    if mandatory is None:
        mandatory = REQUIRED
    known = set(['AGENT-DESIGN', 'AGENT-SECURITY', 'AGENT-GOVERNANCE', 'AGENT-INTEGRATION', 'AGENT-INVENTORY', 'AGENT-MATURITY'])
    cited = set(codes) if isinstance(codes, list) else set()
    missing = [c for c in mandatory if c not in cited]
    unknown = [c for c in sorted(cited) if c not in known]
    total = len(known)
    covered = len(cited & known)
    return {
        'valid': not missing and not unknown,
        'missing': missing,
        'unknown': unknown,
        'coverage_report': {
            'total_codes': total,
            'covered_codes': covered,
            'coverage_pct': round(100.0 * covered / total, 1) if total else 0.0,
        },
    }

def agent_check_tool_allowlist(agents, registered_tools):
    problems = []
    agents = agents if isinstance(agents, list) else []
    registered = set(registered_tools) if isinstance(registered_tools, list) else set()
    unknown = set()
    for a in agents:
        if not isinstance(a, dict):
            problems.append('agent entry is not an object')
            continue
        name = a.get('name', '<unnamed>')
        tools = a.get('tools')
        if not tools:
            problems.append('%s has no tools allowlist' % name)
            continue
        for t in tools:
            if registered and t not in registered:
                problems.append('%s references unregistered tool %s' % (name, t))
                unknown.add(t)
    return {
        'valid': not problems,
        'problems': problems,
        'agent_count': len(agents),
        'unknown_tools': sorted(unknown),
    }
